/* ======================= 저장 ======================= */
const KEY='cqs-note-ch1';
const P=(()=>{ try{ return Object.assign({xp:0,read:[],best:{},sound:true,blind:false}, JSON.parse(localStorage.getItem(KEY))||{}); }catch(e){ return {xp:0,read:[],best:{},sound:true,blind:false}; } })();
const save=()=>{ try{ localStorage.setItem(KEY,JSON.stringify(P)); }catch(e){} };

/* ======================= 유틸 ======================= */
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const md=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<mark class="k">$1</mark>');
const shuffle=a=>{ a=a.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.random()*(i+1)|0; [a[i],a[j]]=[a[j],a[i]]; } return a; };
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
function toast(m){ const t=$('toast'); t.textContent=m; t.classList.add('on'); clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove('on'),1600); }
function show(id){ document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('on',s.id==='s-'+id)); window.scrollTo(0,0);
  $('tNotes').classList.toggle('on', id==='notes'||id==='note'); $('tQuiz').classList.toggle('on', id==='quiz'||id==='play'); $('tLab').classList.toggle('on', id==='lab'||id==='labplay'); }

/* sound */
let AC=null;
function tone(f,d,type='triangle',w=0,v=.08){ if(!P.sound) return; try{ AC=AC||new (window.AudioContext||window.webkitAudioContext)(); if(AC.state==='suspended') AC.resume();
  const t=AC.currentTime+w,o=AC.createOscillator(),g=AC.createGain(); o.type=type; o.frequency.setValueAtTime(f,t); g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(.0008,t+d); o.connect(g); g.connect(AC.destination); o.start(t); o.stop(t+d+.02);}catch(e){} }
const SFX={ ok(s){ const b=523*Math.pow(2,Math.min(s,12)/12); tone(b,.1,'square',0,.05); tone(b*1.5,.18,'triangle',.07,.09); }, no(){ tone(220,.2,'sine',0,.1); tone(165,.25,'sine',.08,.08); }, tap(){ tone(700,.04,'square',0,.03); }, win(){ [523,659,784,1047,1319].forEach((f,i)=>tone(f,.18,'square',i*.08,.05)); }, lv(){ [523,784,1047,1568].forEach((f,i)=>tone(f,.2,'triangle',i*.08,.09)); } };
function syncSnd(){ $('snd').textContent=P.sound?'🔊':'🔇'; }
$('snd').onclick=()=>{ P.sound=!P.sound; save(); syncSnd(); }; syncSnd();

/* fx */
function floatAt(el,txt){ const r=el.getBoundingClientRect(); const s=document.createElement('div'); s.className='fx float'; s.textContent=txt; s.style.left=(r.left+r.width/2)+'px'; s.style.top=(r.top)+'px'; document.body.appendChild(s);
  s.animate([{transform:'translate(-50%,-50%) scale(.5)',opacity:0},{transform:'translate(-50%,-90%) scale(1.15)',opacity:1,offset:.25},{transform:'translate(-50%,-200%)',opacity:0}],{duration:RM?10:900,easing:'ease-out'}).onfinish=()=>s.remove(); }
function burst(el,n=10,pool=['✨','⭐','🎉']){ if(RM) return; const r=el.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2;
  for(let i=0;i<n;i++){ const s=document.createElement('div'); s.className='fx'; s.textContent=pool[i%pool.length]; s.style.left=x+'px'; s.style.top=y+'px'; s.style.fontSize=(14+Math.random()*14)+'px'; document.body.appendChild(s);
    const a=Math.random()*Math.PI*2,d=50+Math.random()*90; s.animate([{transform:'translate(-50%,-50%)',opacity:1},{transform:`translate(calc(-50% + ${Math.cos(a)*d}px),calc(-50% + ${Math.sin(a)*d}px)) rotate(${Math.random()*300}deg)`,opacity:0}],{duration:650+Math.random()*300,easing:'cubic-bezier(.2,.8,.3,1)'}).onfinish=()=>s.remove(); } }
function banner(t){ const b=document.createElement('div'); b.className='banner'; b.textContent=t; document.body.appendChild(b);
  b.animate([{transform:'translate(-50%,-50%) scale(.3) rotate(-8deg)',opacity:0},{transform:'translate(-50%,-50%) scale(1.1)',opacity:1,offset:.25},{transform:'translate(-50%,-50%) scale(1)',opacity:1,offset:.75},{transform:'translate(-50%,-70%)',opacity:0}],{duration:RM?600:1100,easing:'ease-out'}).onfinish=()=>b.remove(); }

/* xp */
const TITLES=['컴구 새싹','주판 견습생','톱니 장인','진공관 기사','폰 노이만 제자','부팅 마스터','컴구 고인물','컴구의 신'];
function need(l){ return 200+l*100; }
function lvInfo(){ let l=1,r=P.xp; while(r>=need(l)){ r-=need(l); l++; } return {l,r,n:need(l)}; }
function renderTop(){ const L=lvInfo(); $('lvN').textContent=L.l; $('lvT').textContent=TITLES[Math.min(L.l-1,TITLES.length-1)]; $('xpF').style.width=(L.r/L.n*100)+'%'; $('xpTx').textContent=`${L.r} / ${L.n} XP`; }
function gainXP(n){ const b=lvInfo().l; P.xp+=n; save(); renderTop(); const a=lvInfo().l; if(a>b){ setTimeout(()=>{ banner(`🆙 LEVEL ${a}!`); SFX.lv(); },350); } }

/* ======================= 게이트 그리기 ======================= */
function gshape(t,x,y){
  const S='stroke="var(--ink)" stroke-width="2.5" fill="var(--panel)" stroke-linejoin="round"', L='stroke="var(--ink)" stroke-width="2.5" fill="none"';
  let s = t==='not' ? `<path d="M5 30H30" ${L}/>` : `<path d="M5 20H30M5 40H30" ${L}/>`;
  if(t==='and'||t==='nand') s+=`<path d="M25 10H50A20 20 0 0 1 50 50H25Z" ${S}/>`;
  else if(t==='not') s+=`<path d="M30 12L62 30L30 48Z" ${S}/>`;
  else { s+=`<path d="M22 10Q52 10 74 30Q52 50 22 50Q34 30 22 10Z" ${S}/>`; if(t==='xor') s+=`<path d="M14 10Q26 30 14 50" ${L}/>`; }
  const bub = t==='nand'?74 : t==='nor'?78 : t==='not'?66 : 0;
  if(bub) s+=`<circle cx="${bub}" cy="30" r="4" ${S}/>`;
  const end = bub ? bub+4 : (t==='and'?70:74);
  s+=`<path d="M${end} 30H95" ${L}/>`;
  return `<g transform="translate(${x},${y})">${s}</g>`;
}
/* ======================= 챕터 ======================= */
function CH(){ return CHAPTERS.find(c=>c.id===CUR); }
function setChapter(id){
  const c = CHAPTERS.find(x=>x.id===id) || CHAPTERS[0];
  CUR = c.id; SECS = c.secs; QS = c.qs; P.ch = CUR; save();
  $('chTitle').textContent = `${c.n} ${c.t}`;
  $('chSub').textContent = `${c.secs.length}개 파트 · 파트당 2~3분이면 끝!${c.more?' · '+c.more:''}`;
  $('qTitle').textContent = `${c.n} 퀴즈 아레나`;
  $('mRand').querySelector('span').textContent = `${c.n} 전체에서 10문제`;
  $('chsw').innerHTML = CHAPTERS.map(x=>`<button class="chb ${x.id===CUR?'on':''}" role="tab" aria-selected="${x.id===CUR}" data-id="${x.id}">${x.em} ${x.n}<small>${esc(x.t)}</small></button>`).join('');
  $('chsw').querySelectorAll('.chb').forEach(b=>b.onclick=()=>{ SFX.tap(); setChapter(b.dataset.id); if($('s-lab').classList.contains('on')||$('s-labplay').classList.contains('on')){ renderLabHome(); show('lab'); } else if($('s-quiz').classList.contains('on')||$('s-play').classList.contains('on')){ renderQuizHome(); show('quiz'); } else { renderNotes(); show('notes'); } });
}
/* ======================= 노트 ======================= */
function stars(n){ return '⭐'.repeat(n)+'<span style="opacity:.25">⭐</span>'.repeat(3-n); }
function renderNotes(){
  renderTop();
  const n=SECS.filter(s=>P.read.includes(s.id)).length; $('readBar').style.width=(n/SECS.length*100)+'%'; $('readTx').textContent=`${n}/${SECS.length} 완독`;
  const box=$('noteList'); box.innerHTML='';
  SECS.forEach((s,i)=>{
    const b=document.createElement('button'); b.className='stage';
    b.innerHTML=`<span class="ic" style="background:${s.c}22">${s.em}</span><span class="tx"><span class="nm">${i+1}. ${esc(s.t)}</span><span class="sb">${esc(s.sub)}</span></span><span class="st">${P.read.includes(s.id)?'<span class="done">✓ 완독</span>':''}</span>`;
    b.onclick=()=>{ SFX.tap(); openNote(i); };
    box.appendChild(b);
  });
  if(typeof EDIT!=='undefined'&&EDIT){ const b=document.createElement('button'); b.className='stage'; b.style.outline='2px dashed var(--yellow)'; b.innerHTML='<span class="ic">➕</span><span class="tx"><span class="nm">새 파트 추가</span><span class="sb">편집 모드</span></span>';
    b.onclick=()=>{ SECS.push({id:'u'+Date.now().toString(36),em:'📝',c:'#0B9FD8',t:'새 파트',sub:'',blocks:[{type:'sum',text:''}]}); edDirty(); openNote(SECS.length-1); }; box.appendChild(b); }
}
function block(b){
  const T = b.title ? `<h3 class="btitle">${esc(b.title)}</h3>` : '';
  switch(b.type){
    case 'sum': return `<div class="blk sum"><span class="lbl">💡 한 줄 요약</span><p>${md(b.text)}</p></div>`;
    case 'tip': return `<div class="blk tip"><span class="lbl">🧠 이렇게 외워</span><ul>${b.items.map(x=>`<li>${md(x)}</li>`).join('')}</ul></div>`;
    case 'ex': return `<div class="blk ex"><span class="lbl">⭐ 시험각 (연습문제)</span><ul>${b.items.map(x=>`<li>${md(x)}</li>`).join('')}</ul></div>`;
    case 'facts': return `<div class="blk">${T}<div class="facts">${b.items.map(f=>`<div class="fact"><div class="em">${f.em}</div><div class="ft">${md(f.t)}</div><div class="fd">${md(f.d)}</div></div>`).join('')}</div></div>`;
    case 'timeline': return `<div class="blk">${T}<div class="tl">${b.items.map(it=>`<div class="tli"><div class="y">${esc(it.y)}</div><div><div class="tt">${md(it.t)}</div>${it.d?`<div class="td">${md(it.d)}</div>`:''}</div></div>`).join('')}</div></div>`;
    case 'vs': return `<div class="blk">${T}<div class="vs"><div class="side a"><h4>${esc(b.a.h)}</h4><ul>${b.a.li.map(x=>`<li>${md(x)}</li>`).join('')}</ul></div><div class="mid">VS</div><div class="side b"><h4>${esc(b.b.h)}</h4><ul>${b.b.li.map(x=>`<li>${md(x)}</li>`).join('')}</ul></div></div>${b.common?`<div class="vs-common">🤝 ${md(b.common)}</div>`:''}</div>`;
    case 'table': return `<div class="blk">${T}<div class="tw"><table><thead><tr>${b.head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${b.rows.map(r=>`<tr>${r.map(c=>`<td>${md(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
    case 'flow': return `<div class="blk">${T}<div class="flow">${b.steps.map((s,i)=>`${i?'<div class="arrow">↓</div>':''}<div class="fs"><div class="n">${i+1}</div><div><div class="ft">${md(s.t)}</div><div class="fd">${md(s.d)}</div></div></div>`).join('')}</div></div>`;
    case 'place': return `<div class="blk">${T}<div class="place">${b.cells.map(c=>`<div class="pc ${c[0]==='0'?'zero':''}"><b class="mono">${esc(c[0])}</b><small>${esc(c[1])}</small><i>${esc(c[2])}</i></div>`).join('')}</div><div class="pres">${md(b.result)}</div></div>`;
    case 'calc': { const dir = b.dir==='up' ? '<div class="dir">⬆ 아래→위로 읽기</div>' : b.dir==='down' ? '<div class="dir">⬇ 위→아래로 읽기</div>' : '';
      return `<div class="blk">${T}<div class="calc" style="${dir?`grid-template-rows:repeat(${b.rows.length},auto)`:'grid-template-columns:1fr auto'}">${b.rows.map(r=>`<div class="ce mono">${esc(r[0])}</div><div class="co ${r[1]?'':'empty'}">${esc(r[1])}</div>`).join('')}${dir}</div><div class="pres">${md(b.result)}</div></div>`; }
    case 'group': return `<div class="blk">${T}<div class="grp">${b.groups.map(g=>`<div class="gc"><div class="gb mono">${esc(g[0])}</div><div class="ga">↓</div><div class="gv">${esc(g[1])}</div></div>`).join('')}</div><div class="pres">${md(b.result)}</div></div>`;
    case 'formula': return `<div class="blk">${T}<div class="formula">${b.items.map(f=>`<div class="fr"><span>${esc(f[0])}</span><b class="mono">${esc(f[1])}</b></div>`).join('')}</div></div>`;
    case 'demo': return `<button class="btn go wide demo" data-lab="${b.lab}" data-demo="${b.demo||''}">${esc(b.label)}</button>`;
    case 'img': return `<div class="blk">${T}<figure class="fig"><img src="${IMGS[b.key]}" alt="${esc(b.cap)}" style="${b.w?`max-width:min(${b.w}px,100%)`:''}" loading="lazy"><figcaption>${esc(b.cap)}</figcaption></figure></div>`;
    case 'gallery': return `<div class="blk">${T}<div class="gal">${b.items.map(it=>`<figure class="fig"><img src="${IMGS[it.key]}" alt="${esc(it.cap)}" loading="lazy"><figcaption>${esc(it.cap)}</figcaption></figure>`).join('')}</div></div>`;
    case 'gates': return `<div class="gates">${b.items.map(g=>{ const two=g.rows[0].length===3;
      return `<div class="gate"><div class="gh"><b>${esc(g.n)}</b><span>${esc(g.k)}</span></div><svg viewBox="0 0 100 60" class="gsv" role="img" aria-label="${esc(g.n)} 게이트 심볼">${gshape(g.g,0,0)}</svg><div class="ge mono">${esc(g.e)}</div><div class="gr">${md(g.rule)}</div>
      <table class="gt"><thead><tr>${two?'<th>A</th><th>B</th>':'<th>A</th>'}<th>출력</th></tr></thead><tbody>${g.rows.map(r=>`<tr>${r.slice(0,-1).map(c=>`<td>${c}</td>`).join('')}<td><mark class="k">${r[r.length-1]}</mark></td></tr>`).join('')}</tbody></table><div class="gtip">🧠 ${md(g.tip)}</div></div>`; }).join('')}</div>`;
    case 'circ': { let g=''; b.wires.forEach(w=>{ let pts=[]; for(let i=0;i<w.length;i+=2) pts.push(w[i]+','+w[i+1]); g+=`<polyline points="${pts.join(' ')}" fill="none" stroke="var(--ink)" stroke-width="2.5"/>`; });
      b.gates.forEach(x=>{ g+=gshape(x[0],x[1],x[2]); });
      b.labels.forEach(l=>{ g+=`<text x="${l[0]}" y="${l[1]}" font-size="14" font-weight="900" fill="var(--pink)" text-anchor="middle">${esc(l[2])}</text>`; });
      return `<div class="blk">${T}<div class="tw"><svg viewBox="0 0 ${b.w} ${b.h}" class="csv" role="img" aria-label="${esc(b.title)}">${g}</svg></div>${b.result?`<div class="pres">${md(b.result)}</div>`:''}</div>`; }
    case 'fbits': return `<div class="blk">${T}<div class="fb2">${b.parts.map(p=>`<div class="fp" style="--pc:${p.c}"><div class="fpb mono">${esc(p.bits)}</div><div class="fpl">${esc(p.lab)}</div></div>`).join('')}</div><div class="pres">${md(b.result)}</div></div>`;
    case 'live': { const LV=LIVE[b.k]; return LV?`<div class="blk"><h3 class="btitle">🔌 직접 만져 보기 · ${esc(LV.t)}</h3><div class="livec" data-lv="${b.k}"></div></div>`:''; }
    case 'ref': return `<div class="blk ref"><span class="lbl">📎 참고 · 시험 X</span><p>${md(b.text)}</p></div>`;
    case 'warn': return `<div class="blk warn"><span class="lbl">⚠️ 중요</span><p>${md(b.text)}</p></div>`;
    case 'ring': { const n=b.labels.length, cx=140, cy=140, R=104; let g='';
      g+=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="var(--line)" stroke-width="22"/>`;
      b.labels.forEach((l,i)=>{ const a=(-90+i*360/n)*Math.PI/180, x=cx+R*Math.cos(a), y=cy+R*Math.sin(a), hot=b.hl.includes(i);
        g+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="15" fill="${hot?'var(--red)':'var(--panel)'}" stroke="${hot?'var(--red)':'var(--line)'}" stroke-width="2"/><text x="${x.toFixed(1)}" y="${(y+5).toFixed(1)}" text-anchor="middle" font-size="13" font-weight="900" fill="${hot?'#fff':'var(--ink)'}">${esc(l)}</text>`; });
      g+=`<text x="${cx}" y="${cy-6}" text-anchor="middle" font-size="15" font-weight="900" fill="var(--ink)">${esc(b.center)}</text><text x="${cx}" y="${cy+18}" text-anchor="middle" font-size="22" fill="var(--pink)">↻</text>`;
      return `<div class="blk">${T}<div class="ring"><svg viewBox="0 0 280 280" role="img" aria-label="${esc(b.title)}">${g}</svg><div class="rn">${esc(b.note)}</div></div></div>`; }
    case 'layers': return `<div class="blk">${T}<div class="layers">${b.items.map(l=>`<div class="layer" style="background:${l.c}">${esc(l.t)}<span>${esc(l.d)}</span></div>`).join('')}</div></div>`;
  }
  return '';
}
let curNote=0;
function openNote(i){
  curNote=i; const s=SECS[i]; const read=P.read.includes(s.id);
  $('notePage').innerHTML=`
    <div class="nhead"><button class="ib" id="nBack" aria-label="목록으로">←</button>
      <div class="ic" style="background:${s.c}33">${s.em}</div>
      <div class="t"><small>PART ${i+1} · ${esc(s.sub)}</small><h2>${esc(s.t)}</h2></div>${EDIT?'<button class="ib" id="secEdit" aria-label="파트 편집">✏️</button>':''}</div>
    <div class="tools">
      <button class="pill ${P.blind?'on':''}" id="blindBtn">${P.blind?'🙈 가리기 ON':'🙈 가리기 모드'}</button>
      <button class="pill" id="revealAll" style="${P.blind?'':'display:none'}">👀 전부 보기</button>
    </div>
    <div id="nBody" class="${P.blind?'blind':''}">${EDIT?'<button class="btn wide" id="edAddTop" style="margin-bottom:12px">➕ 맨 위에 블록 추가</button>':''}${s.blocks.map((b,bi)=>EDIT?edWrap(b,bi):block(b)).join('')}</div>
    <button class="btn ${read?'':'ok'} wide" id="readBtn" ${read?'disabled':''}>${read?'✓ 완독한 파트예요':'✅ 다 읽었어! (+50 XP)'}</button>
    <div class="nav">
      <button class="btn go" id="toQuiz">🎯 이 파트 퀴즈</button>
      <button class="btn" id="nNext">${i<SECS.length-1?'다음 파트 →':'처음으로 ↺'}</button>
    </div>`;
  show('note');
  $('nBody').querySelectorAll('.livec').forEach(liveMount);
  $('nBack').onclick=()=>{ renderNotes(); show('notes'); };
  $('blindBtn').onclick=()=>{ P.blind=!P.blind; save(); SFX.tap(); openNote(i); if(P.blind) toast('보라색 칸을 눌러서 하나씩 확인해요'); };
  $('revealAll').onclick=()=>{ document.querySelectorAll('#nBody mark.k').forEach(m=>m.classList.add('show')); };
  $('nBody').querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{ SFX.tap(); openLab(b.dataset.lab,b.dataset.demo||undefined); });
  $('nBody').onclick=e=>{ const m=e.target.closest('mark.k'); if(m && P.blind){ m.classList.toggle('show'); SFX.tap(); } };
  $('readBtn').onclick=e=>{ if(P.read.includes(s.id)) return; P.read.push(s.id); save(); SFX.win(); burst(e.currentTarget,14); floatAt(e.currentTarget,'+50 XP'); gainXP(50);
    e.currentTarget.disabled=true; e.currentTarget.classList.remove('ok'); e.currentTarget.textContent='✓ 완독한 파트예요';
    if(SECS.every(x=>P.read.includes(x.id))) setTimeout(()=>banner(`📒 ${CH().n} 완독!`),500); };
  $('toQuiz').onclick=()=>startQuiz('sec:'+s.id);
  $('nNext').onclick=()=>{ if(i<SECS.length-1) openNote(i+1); else { renderNotes(); show('notes'); } };
  if(EDIT) edBind(i);
}

/* ======================= 퀴즈 ======================= */
function renderQuizHome(){
  renderTop();
  const box=$('quizList'); box.innerHTML='';
  const npr=QS.filter(q=>q.pr).length;
  if(npr){ const b=document.createElement('button'); b.className='stage'; b.style.outline='3px solid var(--yellow)';
    b.innerHTML=`<span class="ic" style="background:var(--exbg)">📝</span><span class="tx"><span class="nm">교재 연습문제</span><span class="sb">${npr}문제 · 교재 순서대로</span></span><span class="st stars">${stars(P.best[CUR+':prac']||0)}</span>`;
    b.onclick=()=>{ SFX.tap(); startQuiz('prac'); }; box.appendChild(b); }
  SECS.forEach((s,i)=>{
    const n=(QS.filter(q=>q.s===s.id&&!q.pr).length||QS.filter(q=>q.s===s.id).length), best=P.best['sec:'+s.id]||0;
    const b=document.createElement('button'); b.className='stage';
    b.innerHTML=`<span class="ic" style="background:${s.c}22">${s.em}</span><span class="tx"><span class="nm">${i+1}. ${esc(s.t)}</span><span class="sb">${n}문제</span></span><span class="st stars">${stars(best)}</span>`;
    b.onclick=()=>{ SFX.tap(); startQuiz('sec:'+s.id); };
    box.appendChild(b);
  });
}
$('mRand').onclick=()=>startQuiz('rand');
$('mExam').onclick=()=>startQuiz('exam');

let Z=null;
function startQuiz(key){
  let pool, title;
  if(key==='rand'){ pool=shuffle(QS).slice(0,10); title='🔀 전체 랜덤'; }
  else if(key==='exam'){ pool=shuffle(QS.filter(q=>q.ex)); title='⭐ 시험각 모드'; }
  else if(key==='prac'){ pool=QS.filter(q=>q.pr); title='📝 교재 연습문제'; }
  else { const id=key.slice(4); const own=QS.filter(q=>q.s===id&&!q.pr); pool=shuffle(own.length?own:QS.filter(q=>q.s===id)); title=SECS.find(s=>s.id===id).em+' '+SECS.find(s=>s.id===id).t; }
  Z={key,bkey:key.startsWith('sec:')?key:CUR+':'+key,title,qs:pool,i:0,res:[],streak:0,best:0,xp:0};
  show('play'); renderQ();
}
function renderQ(){
  const q=Z.qs[Z.i];
  const opts = q.ox ? ['O','X'] : shuffle(q.ch);
  const sec=SECS.find(s=>s.id===q.s);
  $('playBox').innerHTML=`
    <div class="qtop"><button class="ib" id="qx" aria-label="그만하기">✕</button>
      <div class="qbar">${Z.qs.map((_,k)=>`<i class="${k<Z.i?(Z.res[k]?'ok':'no'):k===Z.i?'cur':''}"></i>`).join('')}</div>
      <div class="streak ${Z.streak>=3?'hot':''}" id="stk">🔥${Z.streak}</div></div>
    <div class="qcard"><div class="qs">${esc(Z.title)} · ${Z.i+1}/${Z.qs.length} · ${sec.em} ${esc(sec.t)}</div><h3>${esc(q.q)}</h3>${q.img?`<img class="qimg" src="${IMGS[q.img]}" alt="문제 그림">`:''}</div>
    <div class="opts ${q.ox?'ox':''}" id="opts">${opts.map((c,k)=>`<button class="opt" data-c="${esc(c)}">${q.ox?esc(c):`<span class="k">${k+1}</span>${esc(c)}`}</button>`).join('')}</div>
    <div class="fb" id="fb"></div>`;
  $('qx').onclick=()=>{ renderQuizHome(); show('quiz'); };
  document.querySelectorAll('#opts .opt').forEach(b=>b.onclick=()=>answer(b));
}
function answer(btn){
  const q=Z.qs[Z.i]; if(Z.locked) return; Z.locked=true;
  const pick=btn.dataset.c, ok = pick===q.ch[0];
  document.querySelectorAll('#opts .opt').forEach(b=>{ b.disabled=true; if(b.dataset.c===q.ch[0]) b.classList.add('right'); else if(b===btn) b.classList.add('wrong'); else b.classList.add('dim'); });
  Z.res[Z.i]=ok;
  const fb=$('fb');
  if(ok){
    Z.streak++; Z.best=Math.max(Z.best,Z.streak);
    const pts=20+Math.min(Z.streak,10)*5; Z.xp+=pts;
    SFX.ok(Z.streak); burst(btn,Z.streak>=3?14:8, Z.streak>=3?['🔥','✨','⭐']:['✨','⭐']); floatAt(btn,`+${pts} XP`);
    if([3,5,10].includes(Z.streak)) setTimeout(()=>banner(`🔥 ${Z.streak}연속!`),200);
    fb.className='fb good on'; fb.innerHTML=`<div class="v">정답! 🎉</div><div class="why">${esc(q.w)}</div><div class="row"><button class="btn" id="nx">${Z.i<Z.qs.length-1?'다음 →':'결과 보기 🏁'}</button></div>`;
  }else{
    Z.streak=0; SFX.no(); btn.classList.add('shake');
    fb.className='fb bad on'; fb.innerHTML=`<div class="v">정답은 "${esc(q.ch[0])}"</div><div class="why">💡 ${esc(q.w)}</div><div class="row"><button class="btn" id="seeNote">📒 노트 보기</button><button class="btn go" id="nx">${Z.i<Z.qs.length-1?'다음 →':'결과 보기 🏁'}</button></div>`;
    $('seeNote').onclick=()=>{ openNote(SECS.findIndex(s=>s.id===q.s)); toast('다 보고 🎯 퀴즈 탭에서 다시 도전!'); };
  }
  const st=$('stk'); st.textContent='🔥'+Z.streak; st.classList.toggle('hot',Z.streak>=3);
  $('nx').onclick=next; $('nx').focus({preventScroll:true});
  fb.scrollIntoView({behavior:RM?'auto':'smooth',block:'nearest'});
}
function next(){ Z.locked=false; Z.i++; if(Z.i>=Z.qs.length) return result(); renderQ(); window.scrollTo(0,0); }
function result(){
  const right=Z.res.filter(Boolean).length, tot=Z.qs.length, acc=right/tot;
  const st = acc>=.9?3: acc>=.7?2: acc>=.4?1:0;
  const rank = acc===1?'S': acc>=.8?'A': acc>=.6?'B':'C';
  if(Z.bkey){ P.best[Z.bkey]=Math.max(P.best[Z.bkey]||0,st); save(); }
  gainXP(Z.xp + (acc===1?100:0));
  const wrongs=Z.qs.map((q,k)=>({q,ok:Z.res[k]})).filter(x=>!x.ok);
  const msg={S:'만점!! 완벽 그 자체 👑',A:'거의 다 왔어요! 💪',B:'좋아요, 틀린 것만 보고 한 번 더!',C:'노트 한 번 훑고 오면 바로 올라가요!'}[rank];
  $('playBox').innerHTML=`<div class="res">
    <div class="rk">${rank}</div><div class="sc">${right} / ${tot}</div><div class="msg">${msg}</div>
    <div class="rg"><div><b>${'⭐'.repeat(st)||'–'}</b><span>별</span></div><div><b>🔥${Z.best}</b><span>최고 연속</span></div><div><b>+${Z.xp+(acc===1?100:0)}</b><span>XP</span></div></div>
    ${wrongs.length?`<div class="wrongs"><h4>📝 틀린 문제 다시 보기</h4>${wrongs.map(w=>`<div class="wr"><div class="q">${esc(w.q.q)}</div><div class="a">✓ ${esc(w.q.ch[0])} — ${esc(w.q.w)}</div><button data-s="${w.q.s}">📒 노트 보기</button></div>`).join('')}</div>`:''}
    <div class="nav" style="margin-top:0">
      ${wrongs.length?'<button class="btn go" id="retryW">🔁 틀린 것만 다시</button>':'<button class="btn go" id="again">🔁 한 번 더</button>'}
      <button class="btn" id="home">퀴즈 목록</button></div></div>`;
  SFX.win(); if(rank==='S') setTimeout(()=>banner('👑 PERFECT!'),300);
  document.querySelectorAll('.wr button').forEach(b=>b.onclick=()=>openNote(SECS.findIndex(s=>s.id===b.dataset.s)));
  if($('retryW')) $('retryW').onclick=()=>{ Z={key:Z.key,title:'🔁 오답 복습',qs:shuffle(wrongs.map(w=>w.q)),i:0,res:[],streak:0,best:0,xp:0}; renderQ(); };
  if($('again')) $('again').onclick=()=>startQuiz(Z.key);
  $('home').onclick=()=>{ renderQuizHome(); show('quiz'); };
}
document.addEventListener('keydown',e=>{
  if(!$('s-play').classList.contains('on') || !Z) return;
  const o=document.querySelectorAll('#opts .opt');
  if(!Z.locked){ const n=+e.key; if(n>=1&&n<=o.length) o[n-1].click(); if(e.key.toLowerCase()==='o' && o.length===2) o[0].click(); if(e.key.toLowerCase()==='x' && o.length===2) o[1].click(); }
  else if(e.key==='Enter' && $('nx')){ e.preventDefault(); $('nx').click(); }
});

/* ======================= 🧪 실습실 ======================= */
P.lab = P.lab || {};
const SUP = {'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹','-':'⁻'};
const sup = n => String(n).split('').map(c=>SUP[c]||c).join('');
function anim(el,c){ if(!el) return; el.classList.remove(c); void el.offsetWidth; el.classList.add(c); }
function labHead(t,sub){ return `<div class="nhead"><button class="ib" id="lBack" aria-label="실습 목록으로">←</button><div class="t"><small>🧪 실습</small><h2>${esc(t)}</h2></div></div>${sub?`<p class="lsub">${esc(sub)}</p>`:''}`; }
function bindBack(){ const b=$('lBack'); if(b) b.onclick=()=>{ renderLabHome(); show('lab'); }; }
function labDone(id, stars, xp){ const prev=P.lab[id]||0; P.lab[id]=Math.max(prev,stars); save(); gainXP(xp); SFX.win(); setTimeout(()=>banner(stars===3?'👑 PERFECT!':'🎉 CLEAR!'),200); }
function labResult(stars,msg,stats,againFn){
  const d=document.createElement('div'); d.className='res lres';
  d.innerHTML=`<div class="rk" style="font-size:3.6rem">${'⭐'.repeat(stars)}${'<span style="opacity:.2">⭐</span>'.repeat(3-stars)}</div><div class="msg">${esc(msg)}</div>${stats?`<div class="rg">${stats.map(s=>`<div><b>${esc(s[0])}</b><span>${esc(s[1])}</span></div>`).join('')}</div>`:''}<div class="nav" style="margin-top:0"><button class="btn go" data-a="again">🔁 다시</button><button class="btn" data-a="back">실습 목록</button></div>`;
  d.querySelector('[data-a="again"]').onclick=againFn;
  d.querySelector('[data-a="back"]').onclick=()=>{ renderLabHome(); show('lab'); };
  $('labBox').appendChild(d); d.scrollIntoView({behavior:RM?'auto':'smooth',block:'center'});
}

