function labTimeline(id, deck, title){
  const cards = shuffle(deck).slice(0, Math.min(9, deck.length));
  const placed=[Object.assign({},cards[0])]; let i=1, right=0, combo=0;
  const box=$('labBox');
  const draw=()=>{
    const cur=cards[i];
    box.innerHTML = labHead(title,'카드를 연표의 알맞은 자리에 끼워 넣어요. 위가 옛날, 아래가 최근!')+
      `<div class="lhud"><span>📇 ${Math.min(i,cards.length-1)}/${cards.length-1}</span><span class="${combo>=3?'hot':''}">🔥 ${combo}</span></div>`+
      (cur?`<div class="tlcard pop"><small>이 카드는 어디에?</small><b>${esc(cur.t)}</b></div>`:'')+
      `<div class="tlist">${placed.map((c,k)=>`${cur?`<button class="gap" data-k="${k}">＋ 여기</button>`:''}<div class="tlc ${c._n?'pop':''} ${c._b?'bad':c._n?'good':''}"><span class="yr">${esc(c.yl||String(c.y))}</span><b>${esc(c.t)}</b></div>`).join('')}${cur?`<button class="gap" data-k="${placed.length}">＋ 여기</button>`:''}</div>`;
    bindBack(); placed.forEach(c=>{ c._n=false; });
    box.querySelectorAll('.gap').forEach(g=>g.onclick=()=>pick(+g.dataset.k,g));
    if(!cur){ const tot=cards.length-1, st=right===tot?3:right>=tot*.7?2:1; labDone(id,st,40+right*10); labResult(st, st===3?'연표 완벽 마스터!':'틀린 카드(빨간색) 연도만 다시 보자!',[[`${right}/${tot}`,'정답'],[`🔥${combo}`,'마지막 연속']],()=>labTimeline(id,deck,title)); }
  };
  const pick=(k,g)=>{
    const c=Object.assign({},cards[i]);
    const ok=(k===0||placed[k-1].y<=c.y)&&(k===placed.length||placed[k].y>=c.y);
    let ck=k; if(!ok){ ck=0; while(ck<placed.length&&placed[ck].y<c.y) ck++; }
    c._n=true; c._b=!ok; placed.splice(ck,0,c); i++;
    if(ok){ right++; combo++; SFX.ok(combo); burst(g,10); if(combo>=3) floatAt(g,`🔥${combo}연속`); } else { combo=0; SFX.no(); toast(`❌ ${c.yl||c.y} → 빨간 칸으로 들어갔어요`); }
    draw();
  };
  draw();
}

