const BOOT=[
 {k:'pw',t:'⚡ 전원 ON',log:'> 전원 ON → PC 레지스터 = ROM BIOS 부트 프로그램 주소',lit:['pw','rom'],h:'일단 전원부터 켜야지!'},
 {k:'cpu',t:'🧠 CPU 점검',log:'> CPU 점검 .................. OK',lit:['cpu'],h:'POST 전에 CPU부터 점검해!'},
 {k:'post',t:'✅ POST',log:'> POST: 버스 · RTC · 비디오 · RAM · 키보드 · 드라이브 ... OK',lit:['dev'],h:'장치들이 정상인지 먼저 점검(POST)!'},
 {k:'mbr',t:'📍 MBR 읽기',log:'> 디스크 첫 번째 섹터(MBR) 읽기 ... OS 위치 발견',lit:['disk'],h:'OS가 어디 있는지 MBR로 먼저 찾아야 해!'},
 {k:'os',t:'🪟 OS를 RAM에 적재',log:'> 운영체제를 RAM에 적재 ████████ 100%',lit:['ram'],h:'init은 OS가 메모리에 올라온 다음!'},
 {k:'init',t:'🏁 init 실행',log:'> init 실행 → 인터럽트 대기 중...',lit:['os'],h:''}];
const PARTS=[['pw','⚡','전원'],['rom','🔒','ROM BIOS'],['cpu','🧠','CPU'],['dev','⌨️','장치'],['disk','💽','디스크'],['ram','💾','RAM'],['os','🪟','OS']];
function labBoot(){
  let n=0, miss=0, t0=0, timer=null; const box=$('labBox');
  box.innerHTML = labHead('부팅 시뮬레이터','컴퓨터를 직접 부팅해 보자! 다음 단계 버튼을 순서대로 눌러요.')+
    `<div class="parts">${PARTS.map(p=>`<div class="part" id="pt-${p[0]}"><b>${p[1]}</b><span>${p[2]}</span></div>`).join('')}</div>
     <div class="term2" id="term"><div class="dim">_ 전원이 꺼져 있습니다</div></div>
     <div class="lhud"><span id="bStep">단계 0/6</span><span id="bTime">⏱ 0.0초</span><span id="bMiss">💥 0</span></div>
     <div class="opts" id="bOpts" style="grid-template-columns:1fr 1fr"></div>`;
  bindBack();
  shuffle(BOOT).forEach(s=>{ const b=document.createElement('button'); b.className='opt'; b.textContent=s.t; b.dataset.k=s.k; b.onclick=()=>press(b); $('bOpts').appendChild(b); });
  const press=b=>{
    if(!t0){ t0=performance.now(); timer=setInterval(()=>{ if(!$('bTime')){ clearInterval(timer); return; } $('bTime').textContent=`⏱ ${((performance.now()-t0)/1000).toFixed(1)}초`; },100); }
    const want=BOOT[n]; const term=$('term');
    if(b.dataset.k===want.k){
      if(n===0) term.innerHTML='';
      const line=document.createElement('div'); line.className='ok'; line.textContent=want.log; term.appendChild(line);
      want.lit.forEach(id=>{ const p=$('pt-'+id); p.classList.add('on'); burst(p,6,['✨','⚡']); });
      b.classList.add('right'); b.disabled=true; SFX.ok(n+1); n++;
      $('bStep').textContent=`단계 ${n}/6`;
      if(n===BOOT.length){ clearInterval(timer); const sec=((performance.now()-t0)/1000).toFixed(1);
        const l=document.createElement('div'); l.className='big'; l.textContent='🖥️ 부팅 완료! 비트 기상 🤖'; term.appendChild(l);
        const st=miss===0?3:miss<=2?2:1; const best=P.lab.bootBest; if(!best||+sec<best){ P.lab.bootBest=+sec; save(); }
        labDone('boot',st,60); labResult(st, miss?'에러 났던 단계 순서만 다시 기억하자!':'완벽한 부팅!',[[`${sec}초`,'시간'],[`${miss}`,'에러'],[`${P.lab.bootBest}초`,'최고 기록']],labBoot); }
    }else{
      miss++; $('bMiss').textContent=`💥 ${miss}`; SFX.no(); anim(b,'shake'); anim(term,'shake');
      const line=document.createElement('div'); line.className='err'; line.textContent=`!! BOOT ERROR: ${BOOT[n].h}`; term.appendChild(line);
      flashTerm();
    }
    term.scrollTop=term.scrollHeight;
  };
  const flashTerm=()=>{ const t=$('term'); t.classList.add('red'); setTimeout(()=>t.classList.remove('red'),350); };
}

/* ---------- 컴퓨터 조립 ---------- */
const SLOTS=[['cpu','🧠','CPU','hw'],['mem','💾','주기억 장치','hw'],['in','⌨️','입력 장치','hw'],['out','🖥️','출력 장치','hw'],['sys','⚙️','시스템 SW','sw'],['app','🎮','응용 SW','sw'],['fw','🔧','펌웨어','sw']];
const ITEMS=[['중앙처리 장치 (연산·제어)','cpu'],['메인 메모리 (RAM)','mem'],['키보드','in'],['마우스','in'],['모니터','out'],['프린터','out'],['운영체제 (Windows)','sys'],['컴파일러','sys'],['워드프로세서','app'],['웹 브라우저','app'],['컴퓨터 게임','app'],['ROM 속 터치스크린 제어 프로그램','fw']];
function labBuild(){
  const items=shuffle(ITEMS); let i=0, miss=0; const filled={}; const box=$('labBox');
  const draw=()=>{
    const cur=items[i];
    box.innerHTML=labHead('컴퓨터 조립','부품·프로그램을 알맞은 칸에 넣어서 컴퓨터를 완성하자!')+
      `<div class="lhud"><span>🔩 ${i}/${items.length}</span><span>💥 ${miss}</span></div>
       <div class="buildbar"><i style="width:${i/items.length*100}%"></i></div>
       ${cur?`<div class="tlcard pop"><small>이건 어디로?</small><b>${esc(cur[0])}</b></div>`:''}
       <div class="slotgrp"><h4>🔩 하드웨어 4요소</h4><div class="slots2">${SLOTS.filter(s=>s[3]==='hw').map(slotBtn).join('')}</div></div>
       <div class="slotgrp"><h4>📀 소프트웨어 · 펌웨어</h4><div class="slots2">${SLOTS.filter(s=>s[3]==='sw').map(slotBtn).join('')}</div></div>`;
    bindBack();
    box.querySelectorAll('.slot2').forEach(b=>b.onclick=()=>put(b));
    if(!cur){ const st=miss===0?3:miss<=2?2:1; labDone('build',st,60); labResult(st,'컴퓨터 완성! 🖥️ HW 4요소 = 중·주·입·출',[[`${items.length-miss}/${items.length}`,'한 번에 성공'],[`${miss}`,'실수']],labBuild); }
  };
  const slotBtn=s=>`<button class="slot2" data-id="${s[0]}"><b>${s[1]}</b><span>${esc(s[2])}</span><small>${(filled[s[0]]||[]).map(x=>esc(x)).join(' · ')||'비어 있음'}</small></button>`;
  const put=b=>{
    const cur=items[i]; if(!cur) return;
    if(b.dataset.id===cur[1]){ (filled[cur[1]]=filled[cur[1]]||[]).push(cur[0]); SFX.ok(i); burst(b,8); i++; draw(); }
    else{ miss++; SFX.no(); anim(b,'shake'); const s=SLOTS.find(x=>x[0]===cur[1]); toast(`❌ 정답: ${s[2]}`); (filled[cur[1]]=filled[cur[1]]||[]).push(cur[0]); i++; setTimeout(draw,500); }
  };
  draw();
}

/* ---------- 비트 조종기 ---------- */
const MIS=[
 {t:'부호 없는 정수 13 만들기',h:'13 = 8 + 4 + 1',ok:v=>v===13},
 {t:'2의 보수로 −1 만들기',h:'모든 비트를 1로!',ok:v=>v===255},
 {t:'2의 보수로 −5 만들기',h:'5(0000 0101)를 만들고 [2의 보수] 버튼!',ok:v=>v===251},
 {t:'부호와 절대값으로 −5 만들기',h:'+5에서 MSB만 1로',ok:v=>v===133},
 {t:'2의 보수 가장 작은 수 (−128)',h:'1000 0000',ok:v=>v===128},
 {t:'2의 보수 가장 큰 수 (+127)',h:'0111 1111 = 7F',ok:v=>v===127},
 {t:'+127에서 [+1]을 눌러 2의 보수 오버플로우!',h:'127 + 1 = ?',ok:(v,ev)=>ev==='tc'},
 {t:'255에서 [+1]을 눌러 부호 없는 오버플로우!',h:'1111 1111에서 +1',ok:(v,ev)=>ev==='un'},
 {t:"ASCII 'A' 만들기",h:'A = 65 = 0100 0001',ok:v=>v===65},
 {t:'실수 2.5 만들기 (부호1·지수3·가수4, 3초과)',h:'2.5 = 1.01 × 2¹ → 지수 1+3 = 100, 가수 0100',ok:v=>v===0b01000100},
 {t:'실수 −0.75 만들기',h:'0.75 = 1.1 × 2⁻¹ → 부호 1, 지수 −1+3 = 010, 가수 1000',ok:v=>v===0b10101000}];
function labBits(){
  let v=0, m=0; const box=$('labBox');
  box.innerHTML=labHead('비트 조종기','비트를 눌러 껐다 켜 보자. 같은 8비트가 해석에 따라 어떻게 달라지는지 바로 보여요!')+
    `<div class="bitrow" id="bitrow"></div>
     <div class="fleg"><span style="--c:var(--pink)">S 부호</span><span style="--c:var(--cyan)">EEE 지수</span><span style="--c:var(--green)">MMMM 가수</span><small>(실수 해석일 때)</small></div>
     <div class="bbtns"><button class="pill" data-op="inc">＋1</button><button class="pill" data-op="dec">－1</button><button class="pill" data-op="not">NOT</button><button class="pill" data-op="tc">2의 보수</button><button class="pill" data-op="zero">0으로</button></div>
     <div class="blk"><div class="interp" id="interp"></div></div>
     <div class="blk"><h3 class="btitle">🎯 미션 <span id="mcnt"></span></h3><div id="mlist" class="mlist"></div></div>`;
  bindBack();
  const row=$('bitrow');
  for(let k=7;k>=0;k--){ const b=document.createElement('button'); b.className='bit'; b.dataset.k=k; b.innerHTML=`<b>0</b><small>${2**k}</small>`; b.style.setProperty('--c', k===7?'var(--pink)':k>=4?'var(--cyan)':'var(--green)'); b.onclick=()=>{ v^=(1<<k); SFX.tap(); upd(); }; row.appendChild(b); }
  box.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>{
    const op=b.dataset.op; let ev=null;
    if(op==='inc'){ if(v===255){ ev='un'; toast('💥 부호 없는 오버플로우! 255 + 1 → 0'); } if(v===127){ ev='tc'; toast('💥 2의 보수 오버플로우! +127 + 1 → −128'); } v=(v+1)&255; }
    if(op==='dec'){ if(v===0) toast('💥 0 − 1 → 255 (부호 없는)'); if(v===128) toast('💥 −128 − 1 → +127 (2의 보수)'); v=(v+255)&255; }
    if(op==='not') v=(~v)&255;
    if(op==='tc') v=((~v)+1)&255;
    if(op==='zero') v=0;
    if(ev){ anim($('bitrow'),'shake'); SFX.no(); }
    SFX.tap(); upd(ev);
  });
  const fl=()=>{ if(v===0) return '0 <small>(special value로 약속)</small>'; const s=v>>7, e=((v>>4)&7)-3, mm=v&15, val=(s?-1:1)*(1+mm/16)*2**e;
    return `${s?'−':'+'}1.${mm.toString(2).padStart(4,'0')} × 2${sup(e)} = <b>${val}</b>`; };
  const upd=(ev)=>{
    [...row.children].forEach(b=>{ const k=+b.dataset.k, on=(v>>k)&1; b.classList.toggle('on',!!on); b.querySelector('b').textContent=on; });
    const tc=v>=128?v-256:v, sm=v===128?'−0':(v>>7?'−':'+')+(v&127);
    const asc=v>=32&&v<=126?`'${String.fromCharCode(v)}'`:v<32?'(제어 문자)':v===127?'(DEL)':'(확장 영역)';
    $('interp').innerHTML=[['2진수',`${v.toString(2).padStart(8,'0').replace(/(\d{4})/,'$1 ')}`],['부호 없는 정수',v],['부호와 절대값',sm],['2의 보수',tc>0?'+'+tc:tc],['16진수',v.toString(16).toUpperCase().padStart(2,'0')],['8진수',v.toString(8)],['ASCII',asc],['실수 (1·3·4)',fl()]].map(r=>`<div class="ir"><span>${r[0]}</span><b class="mono">${typeof r[1]==='number'?r[1]:r[1]}</b></div>`).join('');
    if(m<MIS.length && MIS[m].ok(v,ev)){ const done=m; m++; setTimeout(()=>{ banner(`🎯 미션 ${done+1} 클리어!`); SFX.ok(8); burst($('mlist'),12); drawM(); if(m===MIS.length){ labDone('bits',3,150); labResult(3,'비트 조종 마스터! 같은 비트, 다른 의미 🧠',[[`${MIS.length}`,'미션']],labBits); } },120); }
  };
  const drawM=()=>{ $('mcnt').textContent=`${m}/${MIS.length}`; $('mlist').innerHTML=MIS.map((x,k)=>`<div class="mi ${k<m?'done':k===m?'cur':''}"><span>${k<m?'✅':k===m?'👉':'🔒'}</span><div><b>${esc(x.t)}</b>${k===m?`<button class="hintb">💡 힌트</button><div class="hint" hidden>${esc(x.h)}</div>`:''}</div></div>`).join('');
    const hb=$('mlist').querySelector('.hintb'); if(hb) hb.onclick=()=>{ hb.nextElementSibling.hidden=false; hb.remove(); }; };
  drawM(); upd();
}

/* ---------- 진법 변환 사다리 ---------- */
function labLadder(){
  const n=20+Math.floor(Math.random()*236); let q=n, rows=[], miss=0, t0=performance.now(), phase='div', bin='', groups=[], gi=0;
  const box=$('labBox');
  const draw=()=>{
    let body='';
    if(phase==='div'||phase==='read'){
      body=`<div class="tlcard"><small>① 10진수 → 2진수: ÷2 하고 나머지 고르기</small><b>${n}₍₁₀₎ = ?₍₂₎</b></div>
        <div class="ladder">${rows.map(r=>`<div class="lr"><span class="mono">${r.q} ÷ 2 = ${Math.floor(r.q/2)}</span><b class="rem ${r.hl?'hl':''}">${r.r}</b></div>`).join('')}
        ${phase==='div'?`<div class="lr cur"><span class="mono">${q} ÷ 2 = ?</span><span class="rb"><button data-r="0">나머지 0</button><button data-r="1">나머지 1</button></span></div>`:''}</div>
        ${phase==='read'?`<div class="pres">⬆ 아래에서 위로 읽기 → <b class="mono" id="rd"></b></div>`:''}`;
    }else{
      const base=phase==='hex'?16:8, bits=phase==='hex'?4:3;
      body=`<div class="tlcard"><small>${phase==='hex'?'② 2진수 → 16진수: 4비트씩':'③ 2진수 → 8진수: 3비트씩'}</small><b class="mono">${bin}₍₂₎</b></div>
        <div class="grp">${groups.map((g,k)=>`<div class="gc ${k===gi?'curg':''}"><div class="gb mono">${g.b}</div><div class="ga">↓</div><div class="gv">${g.ans!==undefined?g.ans:'?'}</div></div>`).join('')}</div>
        <div class="keypad">${[...Array(base).keys()].map(d=>`<button data-d="${d}">${d.toString(16).toUpperCase()}</button>`).join('')}</div>`;
    }
    box.innerHTML=labHead('진법 변환 사다리','직접 한 칸씩 계산해 보자. 빠르고 정확하게!')+`<div class="lhud"><span>💥 ${miss}</span><span id="lt">⏱</span></div>`+body;
    bindBack();
    box.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{ const r=+b.dataset.r;
      if(r===q%2){ rows.push({q,r}); q=Math.floor(q/2); SFX.ok(rows.length); if(q===0){ phase='read'; draw(); readUp(); } else draw(); }
      else{ miss++; SFX.no(); anim(b,'shake'); toast(`${q}는 ${q%2?'홀수 → 나머지 1':'짝수 → 나머지 0'}`); setTimeout(draw,400); } });
    box.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{ const d=+b.dataset.d, g=groups[gi];
      if(d===parseInt(g.b,2)){ g.ans=d.toString(16).toUpperCase(); gi++; SFX.ok(gi); if(gi===groups.length){ setTimeout(next,500); } draw(); }
      else{ miss++; SFX.no(); anim(b,'shake'); toast(`${g.b}₍₂₎ = ${parseInt(g.b,2)}`); } });
  };
  const readUp=()=>{ let k=rows.length-1; const tick=()=>{ if(k<0){ setTimeout(()=>{ phase='hex'; setGroups(4); draw(); },900); return; } rows[k].hl=true; bin+=rows[k].r; draw(); $('rd').textContent=bin; SFX.tap(); k--; setTimeout(tick,RM?50:260); }; tick(); };
  const setGroups=sz=>{ const len=Math.ceil(bin.length/sz)*sz; const p=bin.padStart(len,'0'); groups=[]; for(let k=0;k<p.length;k+=sz) groups.push({b:p.slice(k,k+sz)}); gi=0; };
  const next=()=>{ if(phase==='hex'){ phase='oct'; setGroups(3); draw(); return; }
    const sec=((performance.now()-t0)/1000).toFixed(1); const st=miss===0?3:miss<=2?2:1;
    if(!P.lab.ladderBest||+sec<P.lab.ladderBest){ P.lab.ladderBest=+sec; save(); }
    labDone('ladder',st,80);
    labResult(st,`${n}₍₁₀₎ = ${parseInt(bin,2).toString(2)}₍₂₎ = ${n.toString(16).toUpperCase()}₍₁₆₎ = ${n.toString(8)}₍₈₎`,[[`${sec}초`,'시간'],[`${miss}`,'실수'],[`${P.lab.ladderBest}초`,'최고 기록']],labLadder); };
  const tm=setInterval(()=>{ const e=$('lt'); if(!e||!$('s-labplay').classList.contains('on')){ clearInterval(tm); return; } if(phase==='oct'&&gi>=groups.length) return; e.textContent=`⏱ ${((performance.now()-t0)/1000).toFixed(1)}초`; },100);
  draw();
}

/* ---------- 게이트 놀이터 ---------- */
const GF={and:(a,b)=>a&b,or:(a,b)=>a|b,not:a=>1-a,xor:(a,b)=>a^b,nand:(a,b)=>1-(a&b),nor:(a,b)=>1-(a|b)};
const GINFO={and:['AND','둘 다 1일 때만 1','A · B'],or:['OR','하나라도 1이면 1','A + B'],not:['NOT','반대로',"A'"],xor:['XOR','서로 다르면 1','A ⊕ B'],nand:['NAND','둘 다 1일 때만 0',"(AB)'"],nor:['NOR','둘 다 0일 때만 1',"(A + B)'"]};
function labGates(){
  let g='and', A=0, B=0; const seen={}; Object.keys(GF).forEach(k=>seen[k]=new Set()); const box=$('labBox');
  const draw=()=>{
    const one=g==='not', out=one?GF.not(A):GF[g](A,B), key=one?`${A}`:`${A}${B}`;
    seen[g].add(key);
    const rows=one?[[0],[1]]:[[0,0],[0,1],[1,0],[1,1]], need=rows.length, got=seen[g].size;
    const mastered=Object.keys(GF).filter(k=>seen[k].size===(k==='not'?2:4));
    box.innerHTML=labHead('게이트 놀이터','스위치를 눌러서 전구가 언제 켜지는지 직접 확인! 진리표의 모든 줄을 켜 보면 마스터 도장 ✅')+
      `<div class="tabs2">${Object.keys(GF).map(k=>`<button class="pill ${k===g?'on':''}" data-g="${k}">${mastered.includes(k)?'✅ ':''}${GINFO[k][0]}</button>`).join('')}</div>
       <div class="play">
         <div class="sws"><button class="sw ${A?'on':''}" data-s="A"><span>A</span><b>${A}</b></button>${one?'':`<button class="sw ${B?'on':''}" data-s="B"><span>B</span><b>${B}</b></button>`}</div>
         <svg viewBox="0 0 100 60" class="pg">${gshapeLive(g,A,B,out)}</svg>
         <div class="bulb ${out?'on':''}">${out?'💡':'⚫'}<b>${out}</b></div>
       </div>
       <div class="gr" style="margin:6px 0 10px"><b>${GINFO[g][0]}</b> = ${esc(GINFO[g][2])} · ${esc(GINFO[g][1])}</div>
       <table class="gt tt"><thead><tr>${one?'<th>A</th>':'<th>A</th><th>B</th>'}<th>출력</th><th>확인</th></tr></thead><tbody>${rows.map(r=>{ const k=r.join(''), o=one?GF.not(r[0]):GF[g](r[0],r[1]); return `<tr class="${k===key?'cur':''}">${r.map(x=>`<td>${x}</td>`).join('')}<td>${seen[g].has(k)?o:'?'}</td><td>${seen[g].has(k)?'✓':''}</td></tr>`; }).join('')}</tbody></table>
       <div class="lhud"><span>${GINFO[g][0]} ${got}/${need}</span><span>마스터 ${mastered.length}/6</span></div>`;
    bindBack();
    box.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{ g=b.dataset.g; A=0; B=0; SFX.tap(); draw(); });
    box.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{ if(b.dataset.s==='A') A=1-A; else B=1-B; const was=seen[g].size; draw2(was); });
  };
  const draw2=was=>{ const before=Object.keys(GF).filter(k=>seen[k].size===(k==='not'?2:4)).length; draw(); const one=g==='not'; const out=one?GF.not(A):GF[g](A,B);
    if(out) SFX.ok(3); else SFX.tap();
    if(seen[g].size>was && seen[g].size===(one?2:4)){ banner(`✅ ${GINFO[g][0]} 마스터!`); burst(box.querySelector('.bulb'),14); }
    const after=Object.keys(GF).filter(k=>seen[k].size===(k==='not'?2:4)).length;
    if(after===6 && before<6){ labDone('gates',3,120); labResult(3,'게이트 6종 전부 마스터! 🚪',null,labGates); } };
  draw();
}
function gshapeLive(t,a,b,o){
  const on='var(--green)', off='var(--line)';
  let s=gshape(t,0,0);
  const w=(x1,y1,x2,y2,v)=>`<path d="M${x1} ${y1}H${x2}" stroke="${v?on:off}" stroke-width="4" stroke-linecap="round"/>`;
  let wires = t==='not' ? w(2,30,26,30,a) : w(2,20,22,20,a)+w(2,40,22,40,b);
  const end = t==='nand'?78: t==='nor'?82: t==='not'?70: t==='and'?70:74;
  wires += w(end+2,30,98,30,o);
  return s+wires;
}

/* ---------- 회로 퍼즐 ---------- */
const PZ=[
 {t:'불을 켜라: AND',d:'A와 B를 둘 다 켜야만 불이 들어오게!',ins:['A','B'],nodes:[{id:'n1',ar:2,in:['A','B']}],outs:[['X','n1']],tg:v=>[v.A&v.B]},
 {t:'둘 다 꺼야 켜진다',d:'A, B가 모두 0일 때만 불이 켜지게!',ins:['A','B'],nodes:[{id:'n1',ar:2,in:['A','B']}],outs:[['X','n1']],tg:v=>[1-(v.A|v.B)]},
 {t:'달라야 켜진다',d:'A, B가 서로 다를 때만 켜지게!',ins:['A','B'],nodes:[{id:'n1',ar:2,in:['A','B']}],outs:[['X','n1']],tg:v=>[v.A^v.B]},
 {t:'⭐ XOR를 AND·OR·NOT으로',d:'시험 문제! 빈칸 하나로 XOR를 완성해.',ins:['A','B'],nodes:[{id:'n1',t:'or',in:['A','B']},{id:'n2',t:'and',in:['A','B']},{id:'n3',t:'not',in:['n2']},{id:'n4',ar:2,in:['n1','n3']}],outs:[['X','n4']],tg:v=>[v.A^v.B]},
 {t:'반가산기 만들기',d:'S = 합, C = 올림. 1 + 1 = 10₍₂₎!',ins:['A','B'],nodes:[{id:'n1',ar:2,in:['A','B']},{id:'n2',ar:2,in:['A','B']}],outs:[['S','n1'],['C','n2']],tg:v=>[v.A^v.B,v.A&v.B]},
 {t:"X = A'C",d:'A가 0이고 C가 1일 때만 켜지게!',ins:['A','C'],nodes:[{id:'n1',ar:1,in:['A']},{id:'n2',ar:2,in:['n1','C']}],outs:[['X','n2']],tg:v=>[(1-v.A)&v.C]},
 {t:"F = (B + C) · A'",d:'A는 꺼져 있고, B나 C 중 하나라도 켜지면!',ins:['A','B','C'],nodes:[{id:'n1',ar:2,in:['B','C']},{id:'n2',ar:1,in:['A']},{id:'n3',ar:2,in:['n1','n2']}],outs:[['F','n3']],tg:v=>[(v.B|v.C)&(1-v.A)]},
 {t:'⭐ 짝수 패리티 발생기',d:'1의 개수가 홀수일 때 켜지게 (x = a⊕b⊕c)',ins:['a','b','c'],nodes:[{id:'n1',ar:2,in:['a','b']},{id:'n2',ar:2,in:['n1','c']}],outs:[['x','n2']],tg:v=>[v.a^v.b^v.c]},
 {t:'드모르간 체험',d:"A'와 B'로 NAND를 만들어! (AB)' = A' ? B'",ins:['A','B'],nodes:[{id:'n1',t:'not',in:['A']},{id:'n2',t:'not',in:['B']},{id:'n3',ar:2,in:['n1','n2']}],outs:[['X','n3']],tg:v=>[1-(v.A&v.B)]},
 {t:'⭐ 연습문제 Y 회로',d:"Y = (AB + C')' 를 완성해!",ins:['A','B','C'],nodes:[{id:'n1',t:'and',in:['A','B']},{id:'n2',t:'not',in:['C']},{id:'n3',ar:2,in:['n1','n2']},{id:'n4',ar:1,in:['n3']}],outs:[['Y','n4']],tg:v=>[1-((v.A&v.B)|(1-v.C))]}];
function evalPZ(L,pl,v){ const val=Object.assign({},v); const get=r=>val[r];
  L.nodes.forEach(nd=>{ const t=nd.t||pl[nd.id]; const ins=nd.in.map(get); if(!t||ins.some(x=>x===null||x===undefined)){ val[nd.id]=null; return; } val[nd.id]= t==='not'?1-ins[0]: t==='buf'?ins[0]: GF[t](ins[0],ins[1]); });
  return val; }
function labPuzzle(start){
  let li = start!==undefined?start:Math.min(PZ.findIndex((_,k)=>!P.lab['pz'+k])>=0?PZ.findIndex((_,k)=>!P.lab['pz'+k]):0, PZ.length-1);
  let L, pl, sw, sel, tries;
  const box=$('labBox');
  const load=k=>{ li=k; L=PZ[k]; pl={}; sw={}; L.ins.forEach(x=>sw[x]=0); sel=null; tries=0; draw(); };
  const layout=()=>{ const depth={}; L.ins.forEach(x=>depth[x]=0); const cols={};
    L.nodes.forEach(nd=>{ const d=1+Math.max(...nd.in.map(r=>depth[r])); depth[nd.id]=d; (cols[d]=cols[d]||[]).push(nd.id); });
    const maxD=Math.max(...Object.keys(cols).map(Number)); const rowH=78;
    const maxRows=Math.max(L.ins.length,...Object.values(cols).map(c=>c.length));
    const H=maxRows*rowH+10, W=60+maxD*150+70; const pos={};
    L.ins.forEach((x,k)=>{ const y=(H/(L.ins.length))*(k+.5); pos[x]={ox:36,oy:y}; });
    Object.entries(cols).forEach(([d,ids])=>{ ids.forEach((id,j)=>{ const cy=(H/ids.length)*(j+.5); const x=60+(d-1)*150, y=cy-30; pos[id]={x,y,ox:x+95,oy:y+30}; }); });
    return {pos,W,H}; };
  const draw=()=>{
    const {pos,W,H}=layout(); const val=evalPZ(L,pl,sw);
    const col=v=>v===1?'var(--green)':v===0?'var(--line)':'var(--muted)';
    let svg='';
    L.nodes.forEach(nd=>{ const p=pos[nd.id]; const pins=nd.in.length===1?[p.y+30]:[p.y+20,p.y+40];
      nd.in.forEach((r,k)=>{ const s=pos[r]; const px=p.x+5, py=pins[k], mx=px-14-k*8;
        svg+=`<polyline points="${s.ox},${s.oy} ${mx},${s.oy} ${mx},${py} ${px},${py}" fill="none" stroke="${col(val[r])}" stroke-width="4" stroke-linejoin="round" ${val[r]===null?'stroke-dasharray="5 5"':''}/>`; }); });
    L.outs.forEach(([name,from])=>{ const s=pos[from]; svg+=`<polyline points="${s.ox},${s.oy} ${W-40},${s.oy}" fill="none" stroke="${col(val[from])}" stroke-width="4"/><circle cx="${W-24}" cy="${s.oy}" r="14" fill="${val[from]===1?'#FFD84A':'var(--panel2)'}" stroke="var(--ink)" stroke-width="2.5"/><text x="${W-24}" y="${s.oy+5}" text-anchor="middle" font-size="13" font-weight="900" fill="var(--ink)">${esc(name)}</text>`; });
    L.ins.forEach(x=>{ const p=pos[x]; svg+=`<circle cx="${p.ox}" cy="${p.oy}" r="5" fill="${col(sw[x])}"/><text x="14" y="${p.oy+5}" text-anchor="middle" font-size="15" font-weight="900" fill="var(--pink)">${esc(x)}</text>`; });
    L.nodes.forEach(nd=>{ const p=pos[nd.id], t=nd.t||pl[nd.id];
      if(t) svg+=`<g ${nd.t?'':`data-node="${nd.id}" class="pzbox"`}>${gshape(t==='buf'?'not':t,p.x,p.y)}${nd.t?'':`<rect x="${p.x+18}" y="${p.y+4}" width="62" height="52" rx="8" fill="transparent" stroke="${sel===nd.id?'var(--cyan)':'transparent'}" stroke-width="3"/>`}</g>`;
      else svg+=`<g data-node="${nd.id}" class="pzbox"><rect x="${p.x+20}" y="${p.y+6}" width="58" height="48" rx="10" fill="var(--panel2)" stroke="${sel===nd.id?'var(--cyan)':'var(--pink)'}" stroke-width="3" stroke-dasharray="6 4"/><text x="${p.x+49}" y="${p.y+38}" text-anchor="middle" font-size="24" font-weight="900" fill="var(--pink)">?</text></g>`; });
    const nd=sel&&L.nodes.find(x=>x.id===sel);
    const pal=nd?(nd.ar===1?['not','buf']:['and','or','xor','nand','nor']):[];
    box.innerHTML=labHead('회로 퍼즐','빈칸(?)을 눌러 게이트를 끼우고, 스위치로 테스트한 뒤 채점!')+
      `<div class="lvls">${PZ.map((_,k)=>{ const s=P.lab['pz'+k]||0, open=k===0||P.lab['pz'+(k-1)]; return `<button class="lv2 ${k===li?'on':''}" data-l="${k}" ${open?'':'disabled'}>${open?k+1:'🔒'}<small>${s?'⭐'.repeat(s):''}</small></button>`; }).join('')}</div>
       <div class="tlcard"><small>LEVEL ${li+1}</small><b>${esc(L.t)}</b><span>${esc(L.d)}</span></div>
       <div class="sws row">${L.ins.map(x=>`<button class="sw ${sw[x]?'on':''}" data-s="${x}"><span>${esc(x)}</span><b>${sw[x]}</b></button>`).join('')}</div>
       <div class="tw"><svg viewBox="0 0 ${W} ${H}" class="pzsv" id="pzsv" style="min-width:${Math.min(W,380)}px">${svg}</svg></div>
       ${nd?`<div class="palette"><small>${nd.ar===1?'입력 1개짜리 칸':'입력 2개짜리 칸'}에 넣을 게이트</small><div>${pal.map(t=>`<button class="pgb" data-t="${t}"><svg viewBox="0 0 100 60">${gshape(t==='buf'?'not':t,0,0)}</svg>${t==='buf'?'<span>그대로(선)</span>':''}</button>`).join('')}</div></div>`:''}
       <button class="btn ok wide" id="grade" style="margin-top:12px">✅ 채점하기</button><div id="gradeBox"></div>`;
    bindBack();
    if(nd){ box.querySelector('.palette').querySelectorAll('.pgb').forEach(b=>{ if(b.dataset.t==='buf') b.querySelector('svg').innerHTML='<path d="M5 30H95" stroke="var(--ink)" stroke-width="3"/>'; }); }
    box.querySelectorAll('[data-l]').forEach(b=>b.onclick=()=>{ SFX.tap(); load(+b.dataset.l); });
    box.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{ sw[b.dataset.s]=1-sw[b.dataset.s]; const o=evalPZ(L,pl,sw); SFX.tap(); draw(); if(L.outs.some(([n,f])=>o[f]===1)) SFX.ok(4); });
    $('pzsv').onclick=e=>{ const g=e.target.closest('[data-node]'); if(!g) return; sel=g.dataset.node; SFX.tap(); draw(); };
    box.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{ pl[sel]=b.dataset.t; sel=null; SFX.ok(2); draw(); });
    $('grade').onclick=grade;
  };
  const grade=()=>{
    if(L.nodes.some(nd=>!nd.t&&!pl[nd.id])){ toast('빈칸(?)을 다 채워 줘!'); SFX.no(); return; }
    tries++;
    const n=L.ins.length, rows=[]; let all=true;
    for(let k=0;k<2**n;k++){ const v={}; L.ins.forEach((x,j)=>v[x]=(k>>(n-1-j))&1); const val=evalPZ(L,pl,v); const mine=L.outs.map(([_,f])=>val[f]); const tg=L.tg(v); const ok=mine.every((m,j)=>m===tg[j]); if(!ok) all=false; rows.push({v,mine,tg,ok}); }
    const gb=$('gradeBox');
    gb.innerHTML=`<div class="tw"><table class="gt tt" style="margin-top:12px"><thead><tr>${L.ins.map(x=>`<th>${esc(x)}</th>`).join('')}${L.outs.map(o=>`<th>목표 ${esc(o[0])}</th><th>내 ${esc(o[0])}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map((r,k)=>`<tr class="gr2" style="opacity:0">${L.ins.map(x=>`<td>${r.v[x]}</td>`).join('')}${r.tg.map((t,j)=>`<td>${t}</td><td>${r.mine[j]}</td>`).join('')}<td>${r.ok?'✅':'❌'}</td></tr>`).join('')}</tbody></table></div>`;
    [...gb.querySelectorAll('.gr2')].forEach((tr,k)=>setTimeout(()=>{ tr.style.opacity=1; rows[k].ok?SFX.tap():SFX.no(); },RM?0:120*k));
    setTimeout(()=>{ if(all){ const st=tries===1?3:tries<=2?2:1; P.lab['pz'+li]=Math.max(P.lab['pz'+li]||0,st); save(); gainXP(40); SFX.win(); banner(`💡 LEVEL ${li+1} CLEAR!`); burst($('grade'),16);
        const cleared=PZ.filter((_,k)=>P.lab['pz'+k]).length; if(cleared===PZ.length){ P.lab.puzzle=3; save(); }
        const nx=document.createElement('button'); nx.className='btn go wide'; nx.style.marginTop='10px'; nx.textContent= li<PZ.length-1?'다음 레벨 →':'🏆 전 레벨 클리어!'; nx.onclick=()=>{ if(li<PZ.length-1) load(li+1); else { renderLabHome(); show('lab'); } }; gb.appendChild(nx); nx.scrollIntoView({behavior:RM?'auto':'smooth',block:'center'}); }
      else { toast('❌ 표시된 줄을 보고 게이트를 바꿔 봐!'); } }, RM?0:120*rows.length+100);
  };
  load(li);
}

/* ---------- 불 대수 증명 퍼즐 ---------- */
const LAWS=['교환','결합','분배','항등','보수','멱등','흡수','드모르간','부정'];
const LAWF={'교환':'a + b = b + a','결합':'(a + b) + c = a + (b + c)','분배':'a(b + c) = ab + ac, a + bc = (a + b)(a + c)','항등':'a + 0 = a, a + 1 = 1, a · 1 = a, a · 0 = 0','보수':"a + a' = 1, a · a' = 0",'멱등':'a + a = a, a · a = a','흡수':'a + ab = a, a(a + b) = a','드모르간':"(ab)' = a' + b', (a + b)' = a' · b'",'부정':"(a')' = a"};
const PROOFS=[
 {t:'흡수 법칙 ① 증명',s:['a + ab','a · 1 + ab','a(1 + b)','a · 1','a'],l:['항등','분배','항등','항등'],w:['a = a · 1','a로 묶어내기','1 + b = 1','a · 1 = a']},
 {t:'흡수 법칙 ② 증명',s:['a(a + b)','aa + ab','a + ab','a'],l:['분배','멱등','흡수'],w:['a를 괄호 안에 곱해 펼치기','aa = a','a + ab = a']},
 {t:"X = A'C 정리",s:["A'B'C + A'BC","A'C(B' + B)","A'C · 1","A'C"],l:['분배','보수','항등'],w:["A'C로 묶기","B' + B = 1","A'C · 1 = A'C"]},
 {t:'OR 진리표 간략화',s:["a'b + ab' + ab","a'b + a(b' + b)","a'b + a · 1","a'b + a","a + b"],l:['분배','보수','항등','분배'],w:["ab' + ab = a(b' + b)","b' + b = 1","a · 1 = a","a + a'b = (a + a')(a + b) = a + b"]},
 {t:'⭐ 연습문제 Y 정리',s:["(AB + C')'","(AB)' · (C')'","(AB)' · C","(A' + B') · C"],l:['드모르간','부정','드모르간'],w:["(x + y)' = x' · y'","(C')' = C","(AB)' = A' + B'"]}];
function labProof(){
  let pi=0, st=0, miss=0, opts=null; const box=$('labBox');
  const draw=()=>{
    const p=PROOFS[pi];
    if(!opts) opts=shuffle([p.l[st],...shuffle(LAWS.filter(x=>x!==p.l[st])).slice(0,3)]);
    box.innerHTML=labHead('불 대수 증명 퍼즐','각 단계에서 어떤 법칙을 썼는지 골라 식을 한 줄씩 풀어 내자!')+
      `<div class="lvls">${PROOFS.map((q,k)=>`<button class="lv2 ${k===pi?'on':''}" data-p="${k}">${k+1}<small>${P.lab['pf'+k]?'✅':''}</small></button>`).join('')}</div>
       <div class="tlcard"><small>PUZZLE ${pi+1}</small><b>${esc(p.t)}</b></div>
       <div class="proof">${p.s.slice(0,st+1).map((e,k)=>`<div class="pe ${k===st&&k>0?'pop':''}"><b class="mono">${k?'= ':''}${esc(e)}</b></div>${k<st?`<div class="pl">↓ <b>${p.l[k]}</b> <span>${esc(p.w[k])}</span></div>`:''}`).join('')}
       ${st<p.l.length?`<div class="pl cur">↓ 어떤 법칙? 🤔</div><div class="opts" style="grid-template-columns:1fr 1fr">${opts.map(o=>`<button class="opt" data-o="${o}">${o} 법칙</button>`).join('')}</div>`:''}</div>`;
    bindBack();
    box.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{ pi=+b.dataset.p; st=0; opts=null; SFX.tap(); draw(); });
    box.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{
      if(b.dataset.o===p.l[st]){ st++; opts=null; SFX.ok(st); draw(); burst(box.querySelector('.pe:last-of-type')||box,8);
        if(st===p.l.length){ P.lab['pf'+pi]=1; save(); gainXP(30); banner('∎ 증명 완료!'); SFX.win();
          const all=PROOFS.every((_,k)=>P.lab['pf'+k]); if(all){ P.lab.proof=miss===0?3:miss<=3?2:1; save(); }
          const nx=document.createElement('button'); nx.className='btn go wide'; nx.style.marginTop='12px'; nx.textContent=pi<PROOFS.length-1?'다음 퍼즐 →':'🏆 모든 증명 완료!'; nx.onclick=()=>{ if(pi<PROOFS.length-1){ pi++; st=0; opts=null; draw(); } else { renderLabHome(); show('lab'); } }; box.appendChild(nx); }
      } else { miss++; SFX.no(); anim(b,'shake'); b.disabled=true; b.classList.add('no'); toast(`💡 ${b.dataset.o} 법칙: ${LAWF[b.dataset.o]}`); } });
  };
  draw();
}

