  bindBack();
  const bitsBtns=(id,get,set)=>{ const el=$(id); el.innerHTML=''; for(let i=3;i>=0;i--){ const bt=document.createElement('button'); bt.className='bit sm'; bt.dataset.i=i; bt.innerHTML=`<b>0</b><small>${i===3?'MSB':2**i}</small>`; bt.style.setProperty('--c',i===3?'var(--pink)':'var(--cyan)'); bt.onclick=()=>{ set(get()^(1<<i)); SFX.tap(); reset(); }; el.appendChild(bt); } };
  bitsBtns('fA',()=>a,v=>a=v); bitsBtns('fB',()=>b,v=>b=v);
  $('fSub').onclick=()=>{ sub=1-sub; SFX.tap(); reset(); };
  const reset=()=>{ stop(); st=0; draw(); };
