/* ---- 회로 실험실용 래치 예제 ---- */
function bSRL(){ const B=CB(); const R=B.add('sw',20,40,'R'), S=B.add('sw',20,170,'S'), g1=B.add('nor',190,30), g2=B.add('nor',190,150), Q=B.add('bulb',400,30,'Q'), Qb=B.add('bulb',400,150,'Q̄');
  B.w(R,0,g1,0); B.w(g2,0,g1,1); B.w(g1,0,g2,0); B.w(S,0,g2,1); B.w(g1,0,Q,0); B.w(g2,0,Qb,0); return B; }
function bSRLn(){ const B=CB(); const S=B.add('sw',20,40,'S̄',1), R=B.add('sw',20,170,'R̄',1), g1=B.add('nand',190,30), g2=B.add('nand',190,150), Q=B.add('bulb',400,30,'Q'), Qb=B.add('bulb',400,150,'Q̄');
  B.w(S,0,g1,0); B.w(g2,0,g1,1); B.w(g1,0,g2,0); B.w(R,0,g2,1); B.w(g1,0,Q,0); B.w(g2,0,Qb,0); return B; }
function bSRFF(){ const B=CB(); const R=B.add('sw',20,30,'R'), S=B.add('sw',20,250,'S'), CK=B.add('sw',20,140,'CK'),
  a1=B.add('and',150,30), a2=B.add('and',150,230), g1=B.add('nor',330,50), g2=B.add('nor',330,210), Q=B.add('bulb',530,50,'Q'), Qb=B.add('bulb',530,210,'Q̄');
  B.w(R,0,a1,0); B.w(CK,0,a1,1); B.w(CK,0,a2,0); B.w(S,0,a2,1); B.w(a1,0,g1,0); B.w(g2,0,g1,1); B.w(g1,0,g2,0); B.w(a2,0,g2,1); B.w(g1,0,Q,0); B.w(g2,0,Qb,0); return B; }
Object.assign(DEMOS,{
 srl:{t:'SR 래치',b:bSRL,info:'S를 켰다가 끄면? Q가 1로 그대로 → 기억!'},
 srln:{t:'NAND 래치',b:bSRLn,info:'S̄를 0으로 내리면 Set (0으로 누르는 래치)'},
 srff:{t:'SR 플립플롭',b:bSRFF,info:'CK가 0이면 S, R을 바꿔도 Q 그대로'}});

