  box.innerHTML=labHead('SR 래치 · 플립플롭 단계별','입력 스위치를 바꾼 다음 ▶ 다음 단계! 한 단계 = 게이트가 한 번 계산하는 시간이에요.')+
    `<div class="tabs2" id="ltMode"></div>
     <div class="tabs2" id="ltIns"></div>
     <div class="stepbar"><button class="pill on" id="ltS">다음 단계 ▶</button><button class="pill" id="ltA">⏩ 안정될 때까지</button><button class="pill" id="ltR">⏮ 처음 상태로</button></div>
     <div class="stepexp" id="ltE"></div>
     <div class="cwrap" style="max-height:none"><svg id="ltSvg" style="display:block;width:100%"></svg></div>
     <div class="lhud" id="ltH"></div>
     <div class="blk" style="margin-top:10px"><h3 class="btitle">📋 기록 (교재 표처럼 자동으로 쌓여요)</h3><div class="tw" id="ltLog"></div></div>
     <div class="blk" style="margin-top:12px"><h3 class="btitle">🎯 미션 <span id="ltMc"></span></h3><div class="mlist" id="ltM"></div></div>`;
  bindBack();
  $('ltS').onclick=()=>{ if(isStable()){ toast('이미 안정(stable)! 스위치를 바꿔 봐'); return; } step(); SFX.ok(Math.min(since,8)); draw(); check(); };
  $('ltA').onclick=()=>{ let k=0; while(!isStable()&&k<8){ step(); k++; } if(k) SFX.ok(5); else toast('이미 안정(stable)!'); draw(); check(); };
  $('ltR').onclick=()=>{ reset(); SFX.tap(); draw(); };
  const toggle=key=>{ const oldCK=v.CK; v[key]=1-v[key]; if(key==='CK'&&!oldCK&&v.CK) highFlips=0; since=0; last=null; pendIn=key; SFX.tap(); if(isStable()){ t++; pushLog(); } draw(); check(); };
  const setMode=k=>{ mode=k; reset(); draw(); };
  const ruleTx=(f,a,b,o)=>f==='nor'?((a|b)?`1이 있으니 → <b>0</b>`:`전부 0이니 → <b>1</b>`):f==='nand'?((a&b)?`전부 1이니 → <b>0</b>`:`0이 있으니 → <b>1</b>`):((a&b)?`둘 다 1 → <b>통과(1)</b>`:`막힘 → <b>0</b>`);
