    if(ff){ gate('a1','and',150,35); gate('a2','and',150,195); }
    gate('Q',L.g.find(x=>x.id==='Q').f,gx,45); gate('Qb',L.g.find(x=>x.id==='Qb').f,gx,185);
    const tg=(k,lb,cx,cy)=>{ g+=`<g class="tgl" data-t="${k}" style="cursor:pointer"><rect x="${cx-32}" y="${cy-15}" width="64" height="30" rx="8" fill="${v[k]?ON:'var(--panel)'}" stroke="${pendIn===k?'var(--yellow)':'var(--ink)'}" stroke-width="${pendIn===k?4:2}"/><text x="${cx}" y="${cy+5}" text-anchor="middle" font-size="13" font-weight="900" fill="${v[k]?'#fff':'var(--ink)'}">${lb}=${v[k]}</text></g>`; };
    if(ff){ tg('R','R',38,55); tg('CK','CK',38,145); tg('S','S',38,235); } else { tg(L.ins[0][0],L.ins[0][1],38,65); tg(L.ins[1][0],L.ins[1][1],38,225); }
    const lamp=(lb,val,cx,cy)=>{ g+=`${val?`<circle cx="${cx}" cy="${cy}" r="21" fill="${ON}" opacity=".35"/>`:''}<circle cx="${cx}" cy="${cy}" r="16" fill="${val?'#8EC5FF':'var(--panel)'}" stroke="${same&&!stable?'var(--red)':'var(--ink)'}" stroke-width="${same?3.5:2.5}"/><text x="${cx}" y="${cy+5}" text-anchor="middle" font-size="13" font-weight="900" fill="var(--ink)">${val}</text><text x="${cx}" y="${cy-24}" text-anchor="middle" font-size="14" font-weight="900" fill="var(--pink)">${lb}</text>`; };
    lamp('Q',v.Q,gx+240,75); lamp('Q̄',v.Qb,gx+240,215);
    const sv=$('ltSvg'); sv.setAttribute('viewBox',`0 0 ${W} 270`); sv.style.minWidth=ff?'440px':'0'; sv.innerHTML=g;
    sv.querySelectorAll('[data-t]').forEach(el=>el.onclick=()=>toggle(el.dataset.t));
    // ---- 설명 ----
    const insTx=L.ins.map(([k,lb])=>`${lb}=${v[k]}`).join(', ');
    let ex;
    if(pendIn){ const lb=L.ins.find(i=>i[0]===pendIn)[1]; ex=`<b>${lb}를 ${v[pendIn]}로 바꿨어요!</b> 게이트는 아직 계산 전. ${stable?'그런데 이 입력으로는 바뀔 게 없어요 → 이미 안정 ✅':'▶ 다음 단계를 눌러 한 단계씩 따라가 보자'}`; }
    else if(last){ const nmG=c=>c.G.nm; const same0=last.calc.filter(c=>c.o===c.old); ex=`<b>${t}단계</b><br>`+last.calc.filter(c=>c.o!==c.old).map(c=>{ const nm=c.G.in.map(k=>k==='Qb_in'?'Q':k==='Qb'?'Q̄':k==='Sn'?'S̄':k==='Rn'?'R̄':k==='a1'?'위 문지기':k==='a2'?'아래 문지기':k); return `• ${c.G.nm}: (${nm[0]}=${c.a}, ${nm[1]}=${c.b}) ${ruleTx(c.G.f,c.a,c.b,c.o)} <b>바뀜!</b>`; }).join('<br>')+(same0.length?`<br><span style="opacity:.7">• 그대로: ${same0.map(nmG).join(', ')}</span>`:'')+
      `<br>${stable?(same?'⚠️ 안정됐지만 <b>Q = Q̄</b> → 부정 상태! 이 입력은 쓰면 안 돼요':'✅ 더 바뀔 게 없음 → <b>stable</b>'):same?'⚠️ <b>Q = Q̄</b> → 아직 <b>unstable</b>. ▶ 한 번 더!':'⏳ 아직 바뀌는 중 → ▶ 한 번 더!'}`; }
    else ex=`<b>현재</b> ${insTx}, Q = ${v.Q}, Q̄ = ${v.Qb}. ${mode==='ff'?'CK = 0이면 문지기가 S, R을 막아요. ':mode==='nand'?'이 래치는 입력을 <b>0</b>으로 눌러야 동작! ':''}스위치를 눌러 입력을 바꿔 보자.`;
