    $('ltE').innerHTML=ex;
    const state=stable?(same?'⚠️ 부정':'✅ stable'):(same?'⚠️ unstable':'⏳ 계산 중');
    $('ltH').innerHTML=`<span>t = ${t}</span><span class="${stable&&!same?'':'hot'}">${state}</span><span>Q = ${v.Q} · Q̄ = ${v.Qb}</span>${mode==='ff'?`<span>CK=1 동안 Q 변화 ${highFlips}번</span>`:''}`;
    const insH=L.ins.map(i=>i[1]);
