    while(opts.size<4){ const t=[...c]; const i=Math.floor(Math.random()*3); t[i]=(t[i]+[5,1,4,6][Math.floor(Math.random()*4)])%10; const x=t[0]*100+t[1]*10+t[2]; if(x>0) opts.add(x); }
