function bQ2(t){ const B=CB(); const A=B.add('sw',20,30,'A'), Bb=B.add('sw',20,180,'B'), g1=B.add(t,160,20), g2=B.add(t,160,170), g3=B.add(t,320,95), g4=B.add(t,470,95), Y=B.add('bulb',620,100,'Y');
  B.w(A,0,g1,0);B.w(A,0,g1,1);B.w(Bb,0,g2,0);B.w(Bb,0,g2,1);B.w(g1,0,g3,0);B.w(g2,0,g3,1);B.w(g3,0,g4,0);B.w(g3,0,g4,1);B.w(g4,0,Y,0); return B; }
function bFFic(t,ins){ const B=CB(); const ys=t==='jkff'||t==='srff'?[30,120,210]:[40,170]; const sw=ins.map((n,k)=>B.add('sw',20,ys[k],n)); const f=B.add(t,200,70);
  sw.forEach((s,k)=>B.w(s,0,f,k)); const Q=B.add('bulb',380,60,'Q'), Qb=B.add('bulb',380,150,'Q̄'); B.w(f,0,Q,0); B.w(f,1,Qb,0); return B; }
