function bRip(n,neg){ const B=CB(); const H=B.add('c1',20,10,'1'), CK=B.add('sw',20,40+n*140,'CK'); const F=[];
  for(let k=0;k<n;k++){ const y=30+(n-1-k)*140; F.push(B.add('tff',240,y,'FF'+k)); const f=F[k]; B.comps[B.comps.length-1].neg=neg; B.w(H,0,f,0); B.w(k?F[k-1]:CK,0,f,1); }
  for(let k=n-1;k>=0;k--){ const q=B.add('bulb',440,50+(n-1-k)*140,'Q'+k); B.w(F[k],0,q,0); } return B; }
