function bSync(n){ const B=CB(); const H=B.add('c1',20,10,'HIGH'), CK=B.add('sw',20,200,'CK'); const F=[]; let prevAnd=null;
  for(let k=0;k<n;k++){ const x=180+k*230; const f=B.add('jkff',x,80,'FF'+k); F.push(f);
    let src=H; if(k===1) src=F[0]; else if(k>1){ const a=B.add('and',x-120,0); B.w(k===2?F[0]:prevAnd,0,a,0); B.w(F[k-1],0,a,1); prevAnd=a; src=a; }
    B.w(src,0,f,0); B.w(CK,0,f,1); B.w(src,0,f,2); }
  for(let k=n-1;k>=0;k--){ const q=B.add('bulb',220+k*230,240,'Q'+k); B.w(F[k],0,q,0); } return B; }
